function saveCharListToStorage(key: string, items: string[]) {
  try {
    window.localStorage.setItem(key, JSON.stringify(items.slice(0, 30)));
  } catch {
    /* Without localStorage, persistence is unavailable, but the app does not crash */
  }
}

